    image: "images/catalog/hotels--1-1.jpg",
    badge: "Новинка",
    material: "ЛДСП",
    desc: "* Комплект на фото дан в качестве примера.\n ** Точную цену комплекта уточняйте у менеджеров компании.\n Комплект мебели \"Гостиница 1\" рассчитан для небольших номеров в классическом стиле\n Клиент всегда возвращается именно в ту гостиницу, где ему было по-настоящему приятно находиться. Причем для того, чтобы обеспечить должный уровень комфорта, владельцу гостиницы совершенно не обязательно вкладывать \"маленькое состояние\" в меблировку каждого номера. С этой задачей легко справляются качественные комплекты корпусной мебели, профессионально разработанные специально под указанные цели.\nИдеальный комплект мебели для гостинцы. Какой он?\n Разнообразные кровати, шкафы, тумбочки, столы, стулья, вешалки, предназначенные для качественной меблировки общежитий и гостиниц, обязаны соответствовать целой группе важнейших требований. В число таких требований входят:\n высокий уровень прочности и износостойк",
